package vn.contractgovernance.api.policy;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.identity.UserDirectory;
import java.time.*;
import java.util.*;

@Service
public class PolicyService {
    private final EntityStore store;private final JsonSupport json;private final Clock clock;private final CalendarService calendar;private final CommandExecutor commands;private final AuditService audit;private final UserDirectory users;private final PolicyConfig configs;private final PolicyRegression regression;private final PolicyEvaluator evaluator;private final PolicySchedule schedule;private final ListQueries lists;
    public PolicyService(EntityStore store,JsonSupport json,Clock clock,CalendarService calendar,CommandExecutor commands,AuditService audit,UserDirectory users,PolicyConfig configs,PolicyRegression regression,PolicyEvaluator evaluator,PolicySchedule schedule,ListQueries lists){this.store=store;this.json=json;this.clock=clock;this.calendar=calendar;this.commands=commands;this.audit=audit;this.users=users;this.configs=configs;this.regression=regression;this.evaluator=evaluator;this.schedule=schedule;this.lists=lists;}
    private Actor current(Actor actor,String...roles){var now=users.actor(actor.id());now.requireRole(roles);return now;}
    private Actor authorize(Actor actor,UUID id,String action){store.lock("User",actor.id());var now=current(actor,action.equals("APPROVE_PUBLICATION")||action.equals("REJECT_PUBLICATION")?"POLICY_REVIEWER":"POLICY_AUTHOR");if(id!=null){var policy=store.require("Policy",id);if(action.equals("APPROVE_PUBLICATION")||action.equals("REJECT_PUBLICATION"))independent(policy,now);}return now;}
    @Transactional(readOnly=true)
    public JsonNode list(Map<String,String> query,Actor actor){var now=current(actor,"POLICY_AUTHOR","POLICY_REVIEWER");return lists.page("Policy",now,query,true,null,List.of(),body->project(new EntityStore.Entity("Policy",UUID.fromString(body.path("id").asString()),null,body.path("version").asInt(),body),now));}
    @Transactional(readOnly=true)
    public JsonNode get(UUID id,Actor actor){var now=current(actor,"POLICY_AUTHOR","POLICY_REVIEWER");return project(store.require("Policy",id),now);}
    public ApiResult create(JsonNode input,String key,Actor actor){return commands.execute(actor,key,"POST","/api/v1/policies",input,null,()->authorize(actor,null,"CREATE"),()->{schedule.lock();configs.validate(input.path("config"));if(input.hasNonNull("cloneFromId")){var source=store.lock("Policy",UUID.fromString(input.path("cloneFromId").asString()));terminal(source);}return createDraft(input.path("config"),current(actor,"POLICY_AUTHOR"),"CREATE",null);});}
    private ApiResult createDraft(JsonNode config,Actor actor,String action,String reason){var body=json.object();body.put("state","DRAFT");body.set("config",json.nfc(config));body.put("configHash",json.hash(config));body.putArray("contributorIds").add(actor.id().toString());body.putNull("effectiveFrom");body.putNull("effectiveTo");body.put("scheduleVersion",schedule.read().version());body.putNull("regressionReport");body.put("createdAt",JsonSupport.timestamp(clock.instant()));body.put("updatedAt",JsonSupport.timestamp(clock.instant()));body.putArray("allowedActions");body.putArray("blockedActions");var saved=store.create("Policy",UUID.randomUUID(),null,body);audit.record(actor,action,saved,reason);return ApiResult.created(project(saved,actor),"/api/v1/policies/"+saved.id());}
    public ApiResult update(UUID id,JsonNode input,String tag,String key,Actor actor){return commands.execute(actor,key,"PUT","/api/v1/policies/"+id,input,tag,()->authorize(actor,id,"UPDATE"),()->{schedule.lock();var source=store.lock("Policy",id);ETags.check(tag,source.version());state(source,"DRAFT");configs.validate(input.path("config"));var body=(ObjectNode)source.body().deepCopy();body.set("config",json.nfc(input.path("config")));body.put("configHash",json.hash(input.path("config")));body.putNull("regressionReport");contribute(body,actor.id());return save(source,body,current(actor,"POLICY_AUTHOR"),"UPDATE",null);});}
    public ApiResult command(UUID id,JsonNode input,String tag,String key,Actor actor){String action=input.path("action").asString();return commands.execute(actor,key,"POST","/api/v1/policies/"+id+"/commands",input,tag,()->authorize(actor,id,action),()->{
        var slots=schedule.activateLocked(schedule.lock());var source=store.lock("Policy",id);ETags.check(tag,source.version());var now=current(actor,action.equals("APPROVE_PUBLICATION")||action.equals("REJECT_PUBLICATION")?"POLICY_REVIEWER":"POLICY_AUTHOR");var body=(ObjectNode)source.body().deepCopy();String reason=input.has("reason")?input.path("reason").asString():null;
        switch(action){
            case "CLONE"->{terminal(source);return createDraft(source.body().path("config"),now,"CLONE",reason);}
            case "RUN_REGRESSION"->{state(source,"DRAFT");body.set("regressionReport",regression.run(source));}
            case "REQUEST_PUBLICATION"->{state(source,"DRAFT");counter(input,slots);futureDate(input.path("effectiveFrom").asString());var stored=source.body().path("regressionReport");if(stored.isNull()||!stored.path("passed").asBoolean()||!input.path("regressionConfigHash").asString().equals(source.body().path("configHash").asString())||!sameReport(stored,regression.run(source)))throw ApiException.of("REGRESSION_FAILED","Cần báo cáo regression đạt trên đúng config hiện tại.");if(slots.futureId()!=null)throw ApiException.of("POLICY_SCHEDULE_CONFLICT","Đã có policy chờ hiệu lực.");body.put("state","IN_REVIEW");body.set("effectiveFrom",input.path("effectiveFrom"));body.put("scheduleVersion",slots.version());}
            case "APPROVE_PUBLICATION"->{state(source,"IN_REVIEW");independent(source,now);counter(input,slots);futureDate(source.body().path("effectiveFrom").asString());if(!sameReport(source.body().path("regressionReport"),regression.run(source))||!source.body().path("regressionReport").path("passed").asBoolean())throw ApiException.of("REGRESSION_FAILED","Báo cáo không còn khớp chính sách.");schedule.reserve(slots,source,LocalDate.parse(source.body().path("effectiveFrom").asString()),now);body.put("state","SCHEDULED");body.put("scheduleVersion",slots.version()+1);}
            case "REJECT_PUBLICATION"->{state(source,"IN_REVIEW");independent(source,now);body.put("state","REJECTED");}
            default->throw ApiException.validation("/action","Command policy không hợp lệ.");
        }
        return save(source,body,now,action,reason);
    });}
    private boolean sameReport(JsonNode left,JsonNode right){if(left.isNull()||left.isMissingNode())return false;var a=(ObjectNode)left.deepCopy();var b=(ObjectNode)right.deepCopy();a.remove("generatedAt");b.remove("generatedAt");return json.hash(a).equals(json.hash(b));}
    private void futureDate(String value){var from=LocalDate.parse(value);if(from.isBefore(calendar.localDate(clock.instant()).plusDays(1)))throw ApiException.validation("/effectiveFrom","Ngày hiệu lực phải từ ngày mai theo Asia/Ho_Chi_Minh.");}
    private void counter(JsonNode input,PolicySchedule.Schedule slots){if(input.path("expectedScheduleVersion").asInt()!=slots.version())throw ApiException.of("POLICY_SCHEDULE_CONFLICT","Schedule đã thay đổi; tải lại policy.");}
    private ApiResult save(EntityStore.Entity source,ObjectNode body,Actor actor,String action,String reason){body.put("updatedAt",JsonSupport.timestamp(clock.instant()));var saved=store.update(source,body);audit.record(actor,action,saved,reason);return ApiResult.ok(project(saved,actor));}
    private static void state(EntityStore.Entity source,String state){if(!source.body().path("state").asString().equals(state))throw ApiException.of("STATE_CONFLICT","Trạng thái policy không cho phép thao tác.");}
    private static void terminal(EntityStore.Entity source){if(!Set.of("REJECTED","RETIRED").contains(source.body().path("state").asString()))throw ApiException.of("STATE_CONFLICT","Chỉ clone chính sách rejected/retired.");}
    private static void independent(EntityStore.Entity source,Actor actor){for(var id:source.body().path("contributorIds"))if(id.asString().equals(actor.id().toString()))throw ApiException.of("SOD_VIOLATION","Reviewer không được thuộc contributors của policy.");}
    private void contribute(ObjectNode body,UUID actor){var ids=body.withArray("contributorIds");for(var id:ids)if(id.asString().equals(actor.toString()))return;if(ids.size()>=50)throw ApiException.validation("/contributorIds","Vượt giới hạn contributors.");ids.add(actor.toString());}
    JsonNode project(EntityStore.Entity source,Actor actor){var body=(ObjectNode)source.body().deepCopy();body.put("scheduleVersion",schedule.read().version());var allowed=body.putArray("allowedActions");var blocked=body.putArray("blockedActions");allowed.add("SIMULATE");String state=body.path("state").asString();if(actor.hasRole("POLICY_AUTHOR")){if(state.equals("DRAFT")){allowed.add("UPDATE");allowed.add("RUN_REGRESSION");if(body.hasNonNull("regressionReport")&&body.path("regressionReport").path("passed").asBoolean())allowed.add("REQUEST_PUBLICATION");else blocked(blocked,"REQUEST_PUBLICATION","REGRESSION_FAILED","Chạy regression trên cấu hình hiện tại.");if(schedule.read().futureId()!=null){remove(allowed,"REQUEST_PUBLICATION");remove(blocked,"REQUEST_PUBLICATION");blocked(blocked,"REQUEST_PUBLICATION","POLICY_SCHEDULE_CONFLICT","Đã có chính sách chờ hiệu lực.");}}if(Set.of("REJECTED","RETIRED").contains(state))allowed.add("CLONE");}if(actor.hasRole("POLICY_REVIEWER")&&state.equals("IN_REVIEW")){boolean independent=true;for(var id:body.path("contributorIds"))independent&=!id.asString().equals(actor.id().toString());for(var action:List.of("APPROVE_PUBLICATION","REJECT_PUBLICATION"))if(independent){if(action.equals("APPROVE_PUBLICATION")&&schedule.read().futureId()!=null)blocked(blocked,action,"POLICY_SCHEDULE_CONFLICT","Đã có chính sách chờ hiệu lực.");else if(action.equals("APPROVE_PUBLICATION")&&LocalDate.parse(body.path("effectiveFrom").asString()).isBefore(calendar.localDate(clock.instant()).plusDays(1)))blocked(blocked,action,"VALIDATION_FAILED","Ngày yêu cầu hiệu lực đã quá gần; reject và clone.");else allowed.add(action);}else blocked(blocked,action,"SOD_VIOLATION","Reviewer đã đóng góp vào nguồn.");}return body;}
    private void remove(tools.jackson.databind.node.ArrayNode values,String action){for(int i=values.size()-1;i>=0;i--)if(values.get(i).isTextual()?values.get(i).asString().equals(action):values.get(i).path("action").asString().equals(action))values.remove(i);}
    private void blocked(tools.jackson.databind.node.ArrayNode values,String action,String code,String reason){var item=json.object();item.put("action",action);item.put("code",code);item.put("reason",reason);values.add(item);}
    @Transactional(readOnly=true)
    public JsonNode simulate(UUID id,JsonNode input,Actor actor){current(actor,"POLICY_AUTHOR","POLICY_REVIEWER");var policy=store.require("Policy",id);var response=json.object();if(input.path("mode").asString().equals("REGRESSION")){response.putNull("evaluation");response.set("regressionReport",regression.run(policy));}else{var facts=json.nfc(input.path("facts"));var evaluation=(ObjectNode)evaluator.evaluate(policy,facts,json.hash(facts),(candidate,role)->{try{return users.actor(candidate).hasRole(role);}catch(ApiException invalid){return false;}},true);var scope=json.object();scope.put("ruleId","TARGET_BRANCH_SCOPE");scope.put("result","REVIEW_REQUIRED");scope.put("sourceKind","HARD_INVARIANT");scope.put("sourceVersion","A1.2.0/B1.2.0");scope.put("actual","NO_TARGET_BRANCH");scope.put("expected","Explicit real target branch");scope.put("message","Simulation giả định; cần kiểm tra target branch khi submit nghiệp vụ.");evaluation.withArray("results").add(scope);response.set("evaluation",evaluation);response.putNull("regressionReport");}return response;}
}


